/**
 * ============================================================================
 *  MemoryPool<T> — 固定大小对象内存池（Fixed-Size Object Memory Pool）
 * ============================================================================
 *
 * 【核心设计思想】
 *
 *  传统 new/delete 每次调用都会走通用分配器（如 glibc malloc），
 *  它需要处理任意大小的请求，内部维护复杂的空闲链表 / 红黑树 / bins，
 *  导致：
 *    1. 分配/释放的时间复杂度 O(log n) 或摊还 O(1) 但常数很大
 *    2. 每次分配都有额外的元数据开销（通常 8~16 字节 header）
 *    3. 容易产生内存碎片（外部碎片 + 内部碎片）
 *
 *  如果你反复分配/释放 同一类型（相同大小）的对象，通用分配器的工作
 *  其实完全是重复的。内存池正是利用这一特点进行优化。
 *
 * 【本实现的架构】
 *
 *  ┌──────────────────────────────────────────────────┐
 *  │              MemoryPool<T>                        │
 *  │  ┌─────────────────────────────────────────────┐  │
 *  │  │  slot_size_  = align(max(sizeof(T),ptr))   │  │
 *  │  │  chunks_per_block_ = 每个 Chunk 的 Slot 数   │  │
 *  │  └─────────────────────────────────────────────┘  │
 *  │                                                  │
 *  │  free_list_ ──► [Slot A] ──► [Slot B] ──► null   │
 *  │                  (空闲链表，头插头取)               │
 *  │                                                  │
 *  │  chunks_:                                         │
 *  │    ┌──────────┐  ┌──────────┐  ┌──────────┐      │
 *  │    │ Chunk #0 │  │ Chunk #1 │  │ Chunk #2 │ ...  │
 *  │    │ [S][S][S]│  │ [S][S][S]│  │ [S][S][S]│      │
 *  │    └──────────┘  └──────────┘  └──────────┘      │
 *  └──────────────────────────────────────────────────┘
 *
 * 【空闲链表原理 —— 隐式空闲链表 (Implicit Free List)】
 *
 *  当一个 Slot 处于空闲状态时，它的内存空间本身不需要存储任何 T 的数据。
 *  我们巧妙地将一个 "指向下一个空闲 Slot" 的指针（FreeNode*）直接写入
 *  这块空闲内存的头部。这样就实现了零额外空间开销的空闲链表：
 *
 *  Slot 空闲时:  [ next_free_ptr | (剩余未用空间) ]
 *  Slot 被分配后: [ 用户使用的 T 对象数据           ]
 *
 *  alloc() = 从链表头部弹出一个节点 (O(1))
 *  dealloc() = 将节点头插回链表 (O(1))
 *
 * 【内存对齐】
 *
 *  1. 每个 Slot 的大小必须 >= max(sizeof(T), sizeof(void*))
 *     因为 FreeNode 至少需要一个指针的空间
 *  2. Slot 大小向上对齐到 alignof(T) 的倍数
 *  3. Chunk 内每个 Slot 的起始地址天然对齐（因为 Chunk 起始地址对齐
 *     且每个 Slot 大小是 alignof(T) 的倍数）
 *  4. 整个 Chunk 的内存通过 aligned_alloc() 分配，保证对齐
 *
 * 【扩展策略】
 *
 *  当 free_list_ 为空（所有 Slot 都被分配出去）时，自动分配一个新的
 *  Chunk（一大块连续内存），将其切分为多个 Slot 并全部加入 free_list_。
 *  这是一种按需增长的策略，避免了一次性分配过多内存。
 *
 * 【限制】
 *
 *  1. 仅支持固定大小的对象（模板参数 T 决定）
 *  2. 不支持自定义构造/析构（需要手动调用 placement new / 析构函数）
 *  3. 不是线程安全的（可加 mutex 扩展）
 *  4. Chunk 一旦分配不会归还给操作系统（池的生命周期结束时统一释放）
 *
 * ============================================================================
 */

#include <cstddef>      // size_t, nullptr_t
#include <cstdint>      // uintptr_t
#include <cstdlib>      // std::aligned_alloc, std::free
#include <cassert>      // assert
#include <new>          // std::bad_alloc
#include <vector>       // 存储所有已分配的 Chunk 指针
#include <type_traits>  // std::alignment_of
#include <iostream>     // 用于调试输出
#include <cstring>      // memset

template <typename T>
class MemoryPool {
public:
    // ========================================================================
    //  构造函数
    //  @param chunks_per_block: 每个 Chunk 包含多少个 Slot（默认 128）
    //  增大此值可以减少 Chunk 分配次数（减少系统调用），但会增加内存浪费
    // ========================================================================
    explicit MemoryPool(std::size_t chunks_per_block = 128)
        : chunks_per_block_(chunks_per_block)
        , free_list_(nullptr)
    {
        // ------------------------------------------------------------------
        //  计算每个 Slot 的大小（含对齐）
        //  Slot 必须足够容纳一个 T 对象，同时也要足够容纳一个 FreeNode*
        //  （因为空闲时我们需要在 Slot 内存储 next 指针）
        // ------------------------------------------------------------------
        slot_size_ = sizeof(T) >= sizeof(FreeNode)
                         ? sizeof(T)
                         : sizeof(FreeNode);

        // 将 slot_size_ 向上对齐到 alignof(T) 的倍数
        // 对齐公式: (size + alignment - 1) & ~(alignment - 1)
        // 这保证了每个 Slot 的起始地址都满足 T 的对齐要求
        const std::size_t alignment = alignof(T);
        slot_size_ = (slot_size_ + alignment - 1) & ~(alignment - 1);

        // Chunk 的对齐要求：取 T 的对齐要求和标准最大对齐（通常 16 字节）的最大值
        // 这样保证 aligned_alloc 分配出来的内存对 SIMD 等也友好
        chunk_alignment_ = alignment > alignof(std::max_align_t)
                               ? alignment
                               : alignof(std::max_align_t);
    }

    // ========================================================================
    //  析构函数 —— 释放所有已分配的 Chunk
    //  注意：不负责调用 T 的析构函数，使用者需自行管理
    // ========================================================================
    ~MemoryPool() {
        for (auto* chunk : chunks_) {
            std::free(chunk);   // 对应 aligned_alloc 分配的内存
        }
        chunks_.clear();
        free_list_ = nullptr;
    }

    // 禁止拷贝和移动（内存池持有原始指针，拷贝会导致 double-free）
    MemoryPool(const MemoryPool&)            = delete;
    MemoryPool& operator=(const MemoryPool&) = delete;
    MemoryPool(MemoryPool&&)                 = delete;
    MemoryPool& operator=(MemoryPool&&)      = delete;

    // ========================================================================
    //  alloc() —— 分配一个可以容纳 T 对象的内存块
    //
    //  算法：
    //    1. 如果 free_list_ 不为空，直接从头部取出一个 Slot 返回 (O(1))
    //    2. 如果 free_list_ 为空，说明所有 Slot 都用完了，
    //       需要分配一个新的 Chunk 并将其中所有 Slot 加入 free_list_
    //
    //  返回：一个对齐的指针，可安全地用于 placement new 构造 T 对象
    //
    //  抛出：std::bad_alloc 如果系统内存不足
    // ========================================================================
    T* alloc() {
        // 如果空闲链表为空，需要扩展（分配新的 Chunk）
        if (!free_list_) {
            allocateNewChunk();
        }

        // 从空闲链表头部弹出一个节点
        // FreeNode* 指向的就是空闲 Slot 的起始地址
        FreeNode* slot = free_list_;
        free_list_ = free_list_->next;

        // 将 Slot 的起始地址强制转换为 T* 返回
        // 由于我们保证了对齐，这个转换是安全的
        return reinterpret_cast<T*>(slot);
    }

    // ========================================================================
    //  dealloc() —— 将之前分配的内存块归还给内存池
    //
    //  算法（头插法）：
    //    1. 将待归还的 Slot 起始地址解释为 FreeNode*
    //    2. 让它的 next 指向当前的 free_list_ 头
    //    3. 更新 free_list_ 指向它
    //
    //  时间复杂度：O(1)
    //
    //  @param ptr: 之前由 alloc() 返回的指针
    //
    //  注意：
    //    - 不调用 T 的析构函数，使用者需在调用 dealloc 前自行析构
    //    - 传入非法指针（非本池分配的）将导致未定义行为
    // ========================================================================
    void dealloc(T* ptr) {
        if (!ptr) return;   // 空指针不处理

        // 将归还的内存块 reinterpret 为 FreeNode
        // 因为该内存块现在空闲了，我们可以安全地在其头部写入指针
        FreeNode* node = reinterpret_cast<FreeNode*>(ptr);

        // 头插法：新归还的节点成为链表头
        node->next = free_list_;
        free_list_ = node;
    }

    // ========================================================================
    //  统计接口（用于测试和调试）
    // ========================================================================

    /// 已分配的 Chunk 数量
    std::size_t chunkCount() const { return chunks_.size(); }

    /// 每个 Chunk 的 Slot 数量
    std::size_t slotsPerChunk() const { return chunks_per_block_; }

    /// 每个 Slot 的字节大小（含对齐填充）
    std::size_t slotSize() const { return slot_size_; }

    /// 当前空闲链表中的 Slot 数量（遍历链表计数，O(n)，仅用于测试）
    std::size_t freeCount() const {
        std::size_t count = 0;
        for (FreeNode* node = free_list_; node != nullptr; node = node->next) {
            ++count;
        }
        return count;
    }

private:
    // ========================================================================
    //  内部数据结构
    // ========================================================================

    /// 空闲链表节点 —— 直接复用空闲 Slot 的内存空间来存储
    struct FreeNode {
        FreeNode* next;     // 指向下一个空闲 Slot
    };

    /// Chunk 描述 —— 实际上只需要记住指针用于析构时 free()
    /// 这里用 vector<void*> 存储所有 Chunk 的起始地址

    // ========================================================================
    //  成员变量
    // ========================================================================
    std::size_t  slot_size_;            // 每个 Slot 的字节数（已对齐）
    std::size_t  chunks_per_block_;     // 每个 Chunk 包含的 Slot 数
    std::size_t  chunk_alignment_;      // Chunk 内存的对齐要求
    FreeNode*    free_list_;            // 空闲链表头指针
    std::vector<void*> chunks_;         // 所有已分配的 Chunk 指针（用于析构释放）

    // ========================================================================
    //  allocateNewChunk() —— 分配一个新的 Chunk 并初始化空闲链表
    //
    //  步骤：
    //    1. 计算 Chunk 总大小 = slot_size_ * chunks_per_block_
    //    2. 使用 aligned_alloc 分配对齐的大块内存
    //    3. 将大块内存切分为 chunks_per_block_ 个 Slot
    //    4. 每个 Slot 用 FreeNode 串联到空闲链表
    //
    //  ★ 为什么用 aligned_alloc 而不是 new？
    //     因为我们需要原始内存（不对 T 构造），且需要控制对齐方式。
    //     aligned_alloc(C++17) 满足这两个需求。
    // ========================================================================
    void allocateNewChunk() {
        // 计算 Chunk 需要的总字节数
        const std::size_t block_size = slot_size_ * chunks_per_block_;

        // aligned_alloc(对齐要求, 大小)
        // 要求：大小必须是对齐的整数倍（我们的 slot_size_ 已对齐，所以乘积也对齐）
        void* chunk = std::aligned_alloc(chunk_alignment_, block_size);
        if (!chunk) {
            throw std::bad_alloc();
        }

        // 记录 Chunk 指针，以便析构时释放
        chunks_.push_back(chunk);

        // 将大块内存切分为 Slot，串成空闲链表
        // 使用头插法：第一个 Slot 成为链表尾，最后一个 Slot 成为链表头
        // 这样分配时从头取（地址递增），有利于缓存局部性
        char* current = static_cast<char*>(chunk);

        for (std::size_t i = 0; i < chunks_per_block_; ++i) {
            // 将当前 Slot 解释为 FreeNode
            FreeNode* node = reinterpret_cast<FreeNode*>(current);

            // 指向下一个 Slot（地址偏移 slot_size_ 字节）
            // 最后一个 Slot 的 next 设为当前 free_list_（可能为 null）
            if (i < chunks_per_block_ - 1) {
                node->next = reinterpret_cast<FreeNode*>(current + slot_size_);
            } else {
                node->next = free_list_;
            }

            current += slot_size_;
        }

        // 更新 free_list_ 指向新 Chunk 的第一个 Slot
        free_list_ = reinterpret_cast<FreeNode*>(static_cast<char*>(chunk));
    }
};
"}

{"file_path": "main.cpp", "old_string": "", "new_string": "/**
 * ============================================================================
 *  MemoryPool 完整测试套件
 * ============================================================================
 *  测试内容：
 *    1. 基本功能测试 —— alloc / dealloc 循环
 *    2. 内存对齐测试
 *    3. 边界条件测试 —— 大量分配 / 全分配后释放再分配
 *    4. 自动扩展测试 —— 耗尽 Chunk 后自动扩展
 *    5. 生命周期测试 —— placement new + 析构
 *    6. 性能对比测试 —— MemoryPool vs new/delete
 * ============================================================================
 */

#include "memory_pool.h"
#include <iostream>
#include <vector>
#include <chrono>
#include <cassert>
#include <cstring>
#include <iomanip>
#include <algorithm>
#include <numeric>

// 辅助宏：测试断言
#define TEST_ASSERT(cond, msg)                                              \
    do {                                                                    \
        if (!(cond)) {                                                      \
            std::cerr << "  [FAIL] " << __FUNCTION__ << ": " << msg        \
                      << "  (" << #cond << ")" << std::endl;               \
            return false;                                                   \
        }                                                                   \
    } while (0)

#define TEST_PASS(name)  std::cout << "  [PASS] " << (name) << std::endl
#define RUN_TEST(func)   do { if (func()) TEST_PASS(#func);                \
                              else { std::cerr << "  !!! TEST FAILED !!!\n"; \
                                     ++fail_count; } } while(0)

static int fail_count = 0;

// ========================================================================
//  测试用对象类型
// ========================================================================

/// 简单 POD 类型（4 字节）
struct SmallObj {
    int data;
};

/// 中等大小类型（64 字节），带构造/析构计数
struct MediumObj {
    int    id;
    double values[7];
    static int alive_count;
    MediumObj() : id(0) { std::memset(values, 0, sizeof(values)); ++alive_count; }
    MediumObj(int i) : id(i) { std::memset(values, 0, sizeof(values)); ++alive_count; }
    ~MediumObj() { --alive_count; }
};
int MediumObj::alive_count = 0;

/// 大对象（256 字节），测试大块对齐
struct alignas(64) LargeObj {
    char buffer[256];
    static int alive_count;
    LargeObj() { std::memset(buffer, 0xAA, sizeof(buffer)); ++alive_count; }
    ~LargeObj() { --alive_count; }
};
int LargeObj::alive_count = 0;

/// 超大对齐对象（要求 128 字节对齐），验证对齐处理
struct alignas(128) AlignedObj {
    uint64_t value;
    char padding[120];
};

// ========================================================================
//  测试 1：基本 alloc / dealloc 功能
// ========================================================================
bool test_basic_alloc_dealloc() {
    MemoryPool<MediumObj> pool(16); // 每 Chunk 16 个 Slot

    // 分配单个对象
    MediumObj* p1 = pool.alloc();
    TEST_ASSERT(p1 != nullptr, "alloc 应返回非空指针");

    // 用 placement new 构造
    new (p1) MediumObj(42);
    TEST_ASSERT(p1->id == 42, "对象构造后 id 应为 42");

    // 析构并归还
    p1->~MediumObj();
    pool.dealloc(p1);

    // 分配多个对象
    std::vector<MediumObj*> ptrs;
    for (int i = 0; i < 100; ++i) {
        MediumObj* p = pool.alloc();
        new (p) MediumObj(i);
        ptrs.push_back(p);
    }

    // 验证所有指针不同且值正确
    for (size_t i = 0; i < ptrs.size(); ++i) {
        TEST_ASSERT(ptrs[i] != nullptr, "指针非空");
        TEST_ASSERT(static_cast<int>(i) == ptrs[i]->id, "id 值正确");
    }

    // 验证指针唯一（无重复分配同一个 Slot）
    auto sorted_ptrs = ptrs;
    std::sort(sorted_ptrs.begin(), sorted_ptrs.end());
    auto last = std::unique(sorted_ptrs.begin(), sorted_ptrs.end());
    TEST_ASSERT(last == sorted_ptrs.end(), "所有指针应唯一");

    // 释放全部
    for (auto* p : ptrs) {
        p->~MediumObj();
        pool.dealloc(p);
    }

    TEST_ASSERT(MediumObj::alive_count == 0, "所有对象已析构");
    return true;
}

// ========================================================================
//  测试 2：内存对齐验证
// ========================================================================
bool test_alignment() {
    // 测试 SmallObj（4 字节对齐）
    {
        MemoryPool<SmallObj> pool;
        SmallObj* p = pool.alloc();
        auto addr = reinterpret_cast<std::uintptr_t>(p);
        TEST_ASSERT(addr % alignof(SmallObj) == 0,
                     "SmallObj 指针满足 4 字节对齐");
        pool.dealloc(p);
    }

    // 测试 MediumObj（8 字节对齐）
    {
        MemoryPool<MediumObj> pool;
        MediumObj* p = pool.alloc();
        auto addr = reinterpret_cast<std::uintptr_t>(p);
        TEST_ASSERT(addr % alignof(MediumObj) == 0,
                     "MediumObj 指针满足 8 字节对齐");
        pool.dealloc(p);
    }

    // 测试 LargeObj（64 字节对齐）
    {
        MemoryPool<LargeObj> pool;
        for (int i = 0; i < 50; ++i) {
            LargeObj* p = pool.alloc();
            auto addr = reinterpret_cast<std::uintptr_t>(p);
            TEST_ASSERT(addr % alignof(LargeObj) == 0,
                         "LargeObj 指针满足 64 字节对齐");
            pool.dealloc(p);
        }
    }

    // 测试 AlignedObj（128 字节对齐）
    {
        MemoryPool<AlignedObj> pool;
        for (int i = 0; i < 20; ++i) {
            AlignedObj* p = pool.alloc();
            auto addr = reinterpret_cast<std::uintptr_t>(p);
            TEST_ASSERT(addr % alignof(AlignedObj) == 0,
                         "AlignedObj 指针满足 128 字节对齐");
            pool.dealloc(p);
        }
    }

    return true;
}"}

