// ========================================================================
//  测试 3：边界条件 —— 大量分配 / 全分配后释放再分配
// ========================================================================
bool test_boundary_conditions() {
    MemoryPool<SmallObj> pool(8); // 每 Chunk 只有 8 个 Slot，测试频繁扩展

    // 分配 10000 个小对象，触发多次 Chunk 扩展
    std::vector<SmallObj*> ptrs;
    ptrs.reserve(10000);
    for (int i = 0; i < 10000; ++i) {
        SmallObj* p = pool.alloc();
        p->data = i;
        ptrs.push_back(p);
    }
    TEST_ASSERT(pool.freeCount() == 0, "全部分配后空闲数为 0");
    TEST_ASSERT(pool.chunkCount() >= 1250, "应有 >=1250 个 Chunk (10000/8)");

    // 验证数据完整性
    for (int i = 0; i < 10000; ++i) {
        TEST_ASSERT(ptrs[i]->data == i, "数据完整性");
    }

    // 全部归还
    for (auto* p : ptrs) {
        pool.dealloc(p);
    }
    TEST_ASSERT(pool.freeCount() == 10000, "全部归还后空闲数为 10000");

    // 再次全部分配（复用已归还的 Slot，不需要新 Chunk）
    std::size_t chunks_before = pool.chunkCount();
    std::vector<SmallObj*> ptrs2;
    ptrs2.reserve(10000);
    for (int i = 0; i < 10000; ++i) {
        ptrs2.push_back(pool.alloc());
    }
    TEST_ASSERT(pool.chunkCount() == chunks_before,
                 "复用时不应分配新 Chunk");

    for (auto* p : ptrs2) {
        pool.dealloc(p);
    }

    return true;
}

// ========================================================================
//  测试 4：自动扩展 —— Chunk 扩展正确性
// ========================================================================
bool test_auto_expansion() {
    MemoryPool<MediumObj> pool(4); // 每 Chunk 仅 4 个 Slot

    // 初始状态
    TEST_ASSERT(pool.chunkCount() == 0, "初始无 Chunk");

    // 分配 1 个 -> 应触发第一个 Chunk
    MediumObj* p1 = pool.alloc();
    TEST_ASSERT(pool.chunkCount() == 1, "第一次分配触发 Chunk #0");
    TEST_ASSERT(pool.freeCount() == 3, "4 个 Slot 用了 1 个，剩 3");

    // 再分配 3 个 -> 用完第一个 Chunk
    MediumObj* p2 = pool.alloc();
    MediumObj* p3 = pool.alloc();
    MediumObj* p4 = pool.alloc();
    TEST_ASSERT(pool.freeCount() == 0, "第一个 Chunk 用完");

    // 再分配 1 个 -> 应触发第二个 Chunk
    MediumObj* p5 = pool.alloc();
    TEST_ASSERT(pool.chunkCount() == 2, "应有 2 个 Chunk");
    TEST_ASSERT(pool.freeCount() == 3, "第二个 Chunk 用了 1 个，剩 3");

    // 释放 p1 后再分配，应复用
    pool.dealloc(p1);
    TEST_ASSERT(pool.freeCount() == 4, "释放后空闲变为 4");
    MediumObj* p6 = pool.alloc();
    TEST_ASSERT(p6 == p1, "应复用刚释放的 Slot");
    TEST_ASSERT(pool.freeCount() == 3, "复用后空闲变为 3");
    TEST_ASSERT(pool.chunkCount() == 2, "不应增加新 Chunk");

    // 清理
    p2->~MediumObj(); pool.dealloc(p2);
    p3->~MediumObj(); pool.dealloc(p3);
